550	// ── Custom Field Input renderer ─────────────────────────────────────────────
551	
552	interface CustomFieldInputProps {
553	  field: JobFormField;
554	  value: string | boolean | string[] | undefined;
555	  onChange: (val: string | boolean | string[]) => void;
556	  error?: string;
557	  disabled: boolean;
558	}
559	
560	function CustomFieldInput({
561	  field,
562	  value,
563	  onChange,
564	  error,
565	  disabled,
566	}: CustomFieldInputProps) {
567	  const fieldId = `custom-${field.id}`;
568	  const strVal = typeof value === "string" ? value : "";
569	  const boolVal = typeof value === "boolean" ? value : false;
570	  const arrVal = Array.isArray(value) ? value : [];
571	
572	  return (
573	    <div className="space-y-1.5">
574	      <Label htmlFor={fieldId}>
575	        {field.label}
576	        {field.required && <span className="text-destructive ml-1">*</span>}
577	      </Label>
578	
579	      {field.field_type === "text" && (
580	        <Input
581	          id={fieldId}
582	          type="text"
583	          placeholder={field.placeholder ?? ""}
584	          value={strVal}
585	          onChange={(e) => onChange(e.target.value)}
586	          aria-invalid={!!error}
587	          disabled={disabled}
588	        />
589	      )}
590	
591	      {field.field_type === "number" && (
592	        <Input
593	          id={fieldId}
594	          type="number"
595	          placeholder={field.placeholder ?? ""}
596	          value={strVal}
597	          onChange={(e) => onChange(e.target.value)}
598	          aria-invalid={!!error}
599	          disabled={disabled}
600	        />
601	      )}
602	
603	      {field.field_type === "url" && (
604	        <Input
605	          id={fieldId}
606	          type="url"
607	          placeholder={field.placeholder ?? "https://"}
608	          value={strVal}
609	          onChange={(e) => onChange(e.target.value)}
610	          aria-invalid={!!error}
611	          disabled={disabled}
612	        />
613	      )}
614	
615	      {field.field_type === "date" && (
616	        <Input
617	          id={fieldId}
618	          type="date"
619	          value={strVal}
620	          onChange={(e) => onChange(e.target.value)}
621	          aria-invalid={!!error}
622	          disabled={disabled}
623	        />
624	      )}
625	
626	      {field.field_type === "textarea" && (
627	        <Textarea
628	          id={fieldId}
629	          placeholder={field.placeholder ?? ""}
630	          value={strVal}
631	          onChange={(e) => onChange(e.target.value)}
632	          aria-invalid={!!error}
633	          disabled={disabled}
634	          rows={4}
635	          className="resize-none"
636	        />
637	      )}
638	
639	      {field.field_type === "checkbox" && (
640	        <div className="flex items-center gap-2">
641	          <Checkbox
642	            id={fieldId}
643	            checked={boolVal}
644	            onCheckedChange={(checked) => onChange(!!checked)}
645	            aria-invalid={!!error}
646	            disabled={disabled}
647	          />
648	          <Label htmlFor={fieldId} className="text-sm font-normal cursor-pointer">
649	            {field.placeholder ?? "Yes"}
650	          </Label>
651	        </div>
652	      )}
653	
654	      {field.field_type === "select" && (
655	        <Select
656	          value={strVal}
657	          onValueChange={onChange}
658	          disabled={disabled}
659	        >
660	          <SelectTrigger id={fieldId} aria-invalid={!!error}>
661	            <SelectValue placeholder={field.placeholder ?? "Select an option"} />
662	          </SelectTrigger>
663	          <SelectContent>
664	            {(field.options ?? []).map((opt) => (
665	              <SelectItem key={opt} value={opt}>
666	                {opt}
