161	
162	function KanbanColumn({
163	  stage,
164	  stages,
165	  candidates,
166	  onDragStart,
167	  onDragOver,
168	  onDragLeave,
169	  onDrop,
170	  onStageChange,
171	  isDragOver,
172	}: KanbanColumnProps) {
