205	function parseDate(dateStr: string, currentYear: number, currentMonth: number): number {
206	  if (!dateStr) return 0;
207	  const s = dateStr.trim();
208	
209	  // Try "YYYY-MM" or "MM/YYYY" or "YYYY"
210	  const ymd = s.match(/^(\d{4})[\/\-](\d{1,2})/);
211	  if (ymd) return parseInt(ymd[1]) + (parseInt(ymd[2]) - 1) / 12;
212	
213	  const mdy = s.match(/^(\d{1,2})[\/\-](\d{4})/);
214	  if (mdy) return parseInt(mdy[2]) + (parseInt(mdy[1]) - 1) / 12;
215	
216	  // "Jan 2020", "January 2020"
217	  const monthYear = s.match(/^([a-zA-Z]+)\s+(\d{4})/);
218	  if (monthYear) {
219	    const month = monthNameToNum(monthYear[1]);
220	    if (month > 0) return parseInt(monthYear[2]) + (month - 1) / 12;
221	  }
222	
223	  // Plain year "2020"
224	  const plainYear = s.match(/^(\d{4})$/);
225	  if (plainYear) return parseInt(plainYear[1]);
226	
227	  return 0;
228	}
