246	function scoreExperienceBand(years: number, bands: ExperienceBand[]): number {
247	  for (const band of bands) {
248	    if (years >= band.min_years && years < band.max_years) return band.score;
249	  }
250	  // If beyond all bands, return max score
251	  return bands.length > 0 ? bands[bands.length - 1].score : 50;
252	}
