254	function scoreEducation(education: any[], levels: EducationLevel[]): { score: number; highestDegree: string } {
255	  if (!Array.isArray(education) || education.length === 0) {
256	    return { score: 0, highestDegree: "none" };
257	  }
258	
259	  let bestScore = 0;
260	  let bestLevel = "unknown";
261	
262	  for (const edu of education) {
263	    const degree = String(edu.degree || edu.qualification || edu.level || "").toLowerCase().trim();
264	    if (!degree) continue;
265	
266	    for (const level of levels) {
267	      for (const alias of level.aliases) {
268	        if (degree.includes(alias.toLowerCase())) {
269	          if (level.score > bestScore) {
270	            bestScore = level.score;
271	            bestLevel = level.level;
272	          }
273	          break;
274	        }
275	      }
276	    }
277	  }
278	
279	  return { score: bestScore, highestDegree: bestLevel };
280	}
