282	function ruleBasedScoreResume(
283	  parsedJson: any,
284	  jdAnalysis: any,
285	  cfg: {
286	    experience_bands: ExperienceBand[];
287	    education_levels: EducationLevel[];
288	    rule_dimension_weights: Record<string, number>;
289	    must_have_penalty_per_missing: number;
290	    hard_fit_cap: number;
291	    algorithm_version: number;
292	  },
293	) {
294	  const p = parsedJson || {};
295	  const allResumeTerms = extractResumeTerms(parsedJson);
296	
297	  // ── Skill Match ──
298	  const jdSkills = [
299	    ...(jdAnalysis.critical_must_haves || []),
300	    ...(jdAnalysis.preferred_must_haves || []),
301	    ...(jdAnalysis.nice_to_have || []),
302	  ];
303	  const matchedSkills: string[] = [];
304	  const missingSkills: string[] = [];
305	  for (const skill of jdSkills) {
306	    if (fuzzyMatch(skill, allResumeTerms)) matchedSkills.push(skill);
307	    else missingSkills.push(skill);
308	  }
309	  const skillScore = jdSkills.length > 0 ? Math.round((matchedSkills.length / jdSkills.length) * 100) : 50;
310	
311	  // ── Tool Match ──
312	  const jdTools = jdAnalysis.tools || [];
313	  const matchedTools: string[] = [];
314	  const missingTools: string[] = [];
315	  for (const tool of jdTools) {
316	    if (fuzzyMatch(tool, allResumeTerms)) matchedTools.push(tool);
317	    else missingTools.push(tool);
318	  }
319	  const toolScore = jdTools.length > 0 ? Math.round((matchedTools.length / jdTools.length) * 100) : 50;
320	
321	  // ── Experience Fit ──
322	  const rolesWithDates = p.roles_with_dates || [];
323	  const totalYears = extractTotalYears(rolesWithDates);
324	  const requiredYears = extractRequiredYears(jdAnalysis.experience_requirements || "");
325	  let experienceScore = scoreExperienceBand(totalYears, cfg.experience_bands);
326	  if (requiredYears > 0 && totalYears >= requiredYears) {
327	    experienceScore = Math.min(100, experienceScore + 10);
328	  }
329	
330	  // ── Education Fit ──
331	  const education = p.education || [];
332	  const eduResult = scoreEducation(education, cfg.education_levels);
333	  const educationScore = eduResult.score;
334	
335	  // ── Must-Have Coverage ──
336	  const criticalMustHaves = jdAnalysis.critical_must_haves || [];
337	  const matchedMustHaves: string[] = [];
338	  const missingMustHaves: string[] = [];
339	  for (const mh of criticalMustHaves) {
340	    if (fuzzyMatch(mh, allResumeTerms)) matchedMustHaves.push(mh);
341	    else missingMustHaves.push(mh);
342	  }
343	  const mustHaveScore = criticalMustHaves.length > 0
344	    ? Math.round((matchedMustHaves.length / criticalMustHaves.length) * 100) : 100;
345	
346	  // ── Overall Score ──
347	  // Must-haves are handled via penalty only (not as a weighted dimension) to avoid double-counting
348	  const weights = cfg.rule_dimension_weights;
349	  const baseWeight = (weights.skill_match || 0.30) + (weights.experience_fit || 0.25) +
350	    (weights.tool_match || 0.20) + (weights.education_fit || 0.15);
351	  const normalizer = baseWeight > 0 ? 1 / baseWeight : 1; // re-normalize without must_have_coverage
352	  let overallScore =
353	    (skillScore * (weights.skill_match || 0.30) +
354	    experienceScore * (weights.experience_fit || 0.25) +
355	    toolScore * (weights.tool_match || 0.20) +
356	    educationScore * (weights.education_fit || 0.15)) * normalizer;
357	
358	  // Apply must-have penalty (only mechanism for must-have impact — no double-counting)
359	  overallScore -= missingMustHaves.length * cfg.must_have_penalty_per_missing;
360	  overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
361	
362	  // Hard fit check — proportional cap so partial fits rank higher than zero fits
363	  const hardFit = missingMustHaves.length === 0;
364	  if (!hardFit) {
365	    const proportionalCap = Math.max(20, cfg.hard_fit_cap - (missingMustHaves.length - 1) * 10);
366	    overallScore = Math.min(overallScore, proportionalCap);
367	  }
368	
369	  // ── Build strengths & gaps ──
370	  const dimensionScores = [
371	    { name: "Skill Match", score: skillScore },
372	    { name: "Experience", score: experienceScore },
373	    { name: "Tools", score: toolScore },
374	    { name: "Education", score: educationScore },
375	    { name: "Must-Haves", score: mustHaveScore },
376	  ];
377	  dimensionScores.sort((a, b) => b.score - a.score);
378	  const strengths = dimensionScores.filter(d => d.score >= 60).map(d => `${d.name}: ${d.score}%`);
379	  const gaps = dimensionScores.filter(d => d.score < 50).map(d => `${d.name}: ${d.score}%`);
380	
381	  // Add matched skills to strengths
382	  if (matchedMustHaves.length > 0) {
383	    strengths.push(`Matched must-haves: ${matchedMustHaves.join(", ")}`);
384	  }
385	  if (missingMustHaves.length > 0) {
386	    gaps.push(`Missing must-haves: ${missingMustHaves.join(", ")}`);
387	  }
388	
389	  return {
390	    scoring_version: `rule-v1-algo${cfg.algorithm_version}`,
391	    overall_score: overallScore,
392	    hard_fit: hardFit,
393	    // Confidence based on data completeness: skills found + experience parsed + education found
394	    confidence: Math.min(90, Math.round(
395	      (matchedSkills.length > 0 ? 30 : 0) +
396	      (totalYears > 0 ? 30 : 0) +
397	      (educationScore > 0 ? 20 : 0) +
398	      (matchedMustHaves.length > 0 ? 10 : 0)
399	    )),
400	    skill_score: skillScore,
401	    experience_score: experienceScore,
402	    education_score: educationScore,
403	    category_scores_json: {
404	      skill_match: { score: skillScore, matched: matchedSkills, missing: missingSkills },
405	      experience_fit: { score: experienceScore, years_found: totalYears, years_required: requiredYears },
406	      tool_match: { score: toolScore, matched: matchedTools, missing: missingTools },
407	      education_fit: { score: educationScore, highest_degree: eduResult.highestDegree },
408	      must_have_coverage: { score: mustHaveScore, matched: matchedMustHaves, missing: missingMustHaves },
409	    },
410	    matched_must_haves: matchedMustHaves,
411	    missing_must_haves: missingMustHaves,
412	    missing_skills: [...missingMustHaves, ...missingTools],
413	    strengths_json: strengths,
414	    gaps_json: gaps,
415	    interview_questions: [],
416	    explanation_json: {
417	      summary: `Rule-based scoring: ${matchedSkills.length}/${jdSkills.length} skills matched, ${totalYears} years experience (${requiredYears} required), ${eduResult.highestDegree} degree.`,
418	      scoring_mode: "rule_based",
419	      dimension_breakdown: {
420	        skill_match: skillScore,
421	        experience_fit: experienceScore,
422	        tool_match: toolScore,
423	        education_fit: educationScore,
424	        must_have_coverage: mustHaveScore,
425	      },
426	    },
427	  };
428	}
